package fraymus.workspace;
import org.json.*;
import java.nio.file.*;

/** Private hardware development evaluation. Never writes source pixels to the repository. */
public final class TabletopCameraEvaluation {
    public static void main(String[] args)throws Exception{
        Path folder=Path.of(args[0]),project=folder.resolve(args[1]);var pack=new JSONObject(Files.readString(folder.resolve("initial-static-camera.json")));var setup=new JSONObject(Files.readString(folder.resolve("initial-setup.json")));var ledger=new WorldLedger(project);String world=ledger.create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),"Private lighter tabletop development").getString("id");
        try(var original=new WorldObservationStore(project,ledger)){
            var metrics=new MetricObservationStore(project,original,ledger);var g=metrics.geometry(setup.getJSONObject("geometry"));var store=new TabletopStore(project,ledger,metrics);var frames=pack.getJSONArray("frames");var times=pack.getJSONArray("seconds");var first=new JSONObject().put("image",frames.getJSONObject(0).getString("image")).put("imageSha256",frames.getJSONObject(0).getString("imageSha256")).put("seconds",times.getDouble(0));var check=store.check(new JSONObject().put("geometryId",g.getString("id")).put("cameraKey",pack.getString("cameraKey")).put("frame",first).put("pointA",setup.getJSONObject("tape").getJSONArray("pointA")).put("pointB",setup.getJSONObject("tape").getJSONArray("pointB")).put("lengthM",.1016).put("markA",setup.getJSONObject("tape").getDouble("markA")).put("markB",setup.getJSONObject("tape").getDouble("markB")).put("unit",setup.getJSONObject("tape").getString("unit")).put("source",setup.getJSONObject("tape").getString("source")));
            var nativeState=ledger.observe(world);String body=nativeState.getJSONObject("frame").getJSONArray("bodies").getJSONObject(0).getString("id");var result=new JSONObject().put("stage","independent tape check").put("check",check).put("protocol","1e264bc").put("sourceFrames",frames.length()).put("rawImagesPublished",false);
            if(check.getBoolean("passed")){
                var input=new JSONObject().put("worldId",world).put("expectedRevision",nativeState.getInt("expectedRevision")).put("expectedHash",nativeState.getString("expectedHash")).put("geometryId",g.getString("id")).put("checkId",check.getString("id")).put("cameraKey",pack.getString("cameraKey")).put("bodyId",body).put("label","black lighter (user identified)").put("box",setup.getJSONObject("target").getJSONArray("box")).put("frame",first);var run=store.start(input);
                for(int i=1;i<frames.length();i++){var f=frames.getJSONObject(i);var reply=store.frame(new JSONObject().put("id",run.getString("id")).put("generation",0).put("ordinal",i).put("cameraKey",pack.getString("cameraKey")).put("frame",new JSONObject().put("image",f.getString("image")).put("imageSha256",f.getString("imageSha256")).put("seconds",times.getDouble(i))));if(!reply.getJSONObject("run").getString("status").equals("running"))break;}
                var full=store.read(run.getString("id"));if(full.getString("status").equals("running"))store.finish(run.getString("id"));full=store.read(run.getString("id"));var trace=full.getJSONArray("trace");int accepted=0;double mx=0,my=0;var timesMs=new double[trace.length()];
                for(int i=0;i<trace.length();i++){var row=trace.getJSONObject(i);timesMs[i]=row.getDouble("processingMs");var e=row.getJSONObject("estimate");if(e.getBoolean("accepted")){accepted++;mx+=e.getJSONArray("positionM").getDouble(0);my+=e.getJSONArray("positionM").getDouble(1);}}
                double jitter=0;if(accepted>0){mx/=accepted;my/=accepted;for(Object raw:trace){var e=((JSONObject)raw).getJSONObject("estimate");if(e.getBoolean("accepted"))jitter+=Math.pow(e.getJSONArray("positionM").getDouble(0)-mx,2)+Math.pow(e.getJSONArray("positionM").getDouble(1)-my,2);}jitter=Math.sqrt(jitter/accepted);}java.util.Arrays.sort(timesMs);result.put("stage","initial private static clip").put("run",full).put("understanding",store.understanding(run.getString("id"))).put("metrics",new JSONObject().put("frames",trace.length()).put("accepted",accepted).put("acceptedCoverage",trace.isEmpty()?0:accepted/(double)trace.length()).put("stationaryJitterRmsM",jitter).put("medianProcessingMs",trace.isEmpty()?0:timesMs[timesMs.length/2]).put("p95ProcessingMs",trace.isEmpty()?0:timesMs[Math.min(timesMs.length-1,(int)Math.ceil(timesMs.length*.95)-1)]).put("scope","Static stability relative to sample mean, not absolute physical accuracy or unseen motion evaluation"));if(!nativeState.similar(ledger.observe(world)))throw new IllegalStateException("Native state changed");
            }
            Path output=folder.resolve(args[1]+".first.json");Files.writeString(output,result.toString(2),StandardOpenOption.CREATE_NEW);System.out.println(new JSONObject().put("stage",result.getString("stage")).put("tapeErrorM",check.getDouble("absoluteErrorM")).put("tapePassed",check.getBoolean("passed")).put("metrics",result.optJSONObject("metrics")));
        }
    }
}
